import { Ailment } from '../types/enums';
import { ActiveSkill, KiokuArgs, KiokuData, SkillDetail, skillDetailId, SupportIdealPortrait } from '../types/KiokuTypes';
import { KiokuElement, KiokuRole } from '../types/enums';
import { passiveDetailsByMstId, skillDetailsByMstId } from '../utils/helpers';
import { Kioku } from './Kioku';


export class ScoreAttackKioku extends Kioku {
    effects: SkillDetail[];
    idealSupportPortrait: SupportIdealPortrait = SupportIdealPortrait.NONE;
    private scalableEffects: Record<string, SkillDetail> = {};
    private unscalableEffects: Record<string, SkillDetail> = {};
    private buffMult = 1;
    private debuffMult = 1;
    private debuffTurnBonus = 0;

    constructor(
        args: KiokuArgs,
        buffMultReduction = 0,
        debuffMultReduction = 0,
        targetContext?: { role?: KiokuRole; element?: KiokuElement },
    ) {
        super(args);

        // Some calculations need to evaluate a Kioku's support effects against a
        // synthetic role/element without pretending that the underlying character
        // actually has that role/element. This is primarily used by the Kioku Grid
        // support-value chart, where Lux Magica is used for every test context.
        if (targetContext) {
            this.data = {
                ...this.data,
                role: targetContext.role as KiokuData["role"],
                element: targetContext.element as KiokuData["element"],
            };
        }

        this.buffMult -= buffMultReduction / 100;
        this.debuffMult -= debuffMultReduction / 100;

        if (this.support && [this.data.role, this.data.element].includes(this.support.data.support_target)) {
            this.addEffect(passiveDetailsByMstId, this.support.data.support_id, this.support.supportLvl, false);
        }
        if (this.portrait) {
            this.addEffect(passiveDetailsByMstId, this.portrait.passiveSkill1, 6, false);
        }
        for (let i = 1; i <= this.ascension; i++) {
            const passiveId = this.data[`ascension_${i}_effect_2_id` as keyof KiokuData] as number;
            if (passiveId) this.addEffect(passiveDetailsByMstId, passiveId, 1, true);

        }
        this.crys.forEach(c => {
            this.addEffect(passiveDetailsByMstId, 0, c, false, true);
        });

        this.addEffect(skillDetailsByMstId, this.data.special_id, this.specialLvl, true);
        this.addEffect(skillDetailsByMstId, this.data.attack_id, this.attackLvl, true);

        this.addEffect(passiveDetailsByMstId, this.data.ability_id, this.abilityLvl, true);
        let skillId = this.data.skill_id;
        Object.values(this.scalableEffects).forEach(e => {
            if ((e as ActiveSkill).abilityEffectType === "SWITCH_SKILL") {
                skillId = e.value1
            }
        });
        this.addEffect(skillDetailsByMstId, skillId, this.skillLvl, true);

        [...Object.values(this.unscalableEffects), ...Object.values(this.scalableEffects)].forEach(e => {
            if (e.abilityEffectType === "UP_BUFF_EFFECT_VALUE") {
                this.buffMult += e.value1 / 1000;
            } else if (e.abilityEffectType === "UP_DEBUFF_EFFECT_VALUE") {
                this.debuffMult += e.value1 / 1000;
            } else if (e.abilityEffectType === "DWN_BUFF_EFFECT_VALUE") {
                this.buffMult -= e.value1 / 1000;
            } else if (e.abilityEffectType === "DWN_DEBUFF_EFFECT_VALUE") {
                this.debuffMult -= e.value1 / 1000;
            } else if (e.abilityEffectType === "ADDITIONAL_SKILL_ACT") {
                this.addEffect(skillDetailsByMstId, 0, e.value1, true);
            } else if (e.abilityEffectType === "ADD_DEBUFF_TURN") {
                this.debuffTurnBonus += e.value1; // Also increases buffs atm, but since those can't pop it doesn't matter. This is for dot pop
            }
        });

        Object.values(this.scalableEffects).forEach(e => {
            if (e.abilityEffectType === "TSUBAME_LINK") {
                this.scalableEffects[skillDetailId(e).toString() + "1"] = { ...e, abilityEffectType: "UP_ATK_RATIO", value1: e.value2, value2: 0, value3: 0 };
                this.scalableEffects[skillDetailId(e).toString() + "2"] = { ...e, abilityEffectType: "ADDITIONAL_DAMAGE", value1: e.value3, value2: 0, value3: 0 };
                this.scalableEffects[skillDetailId(e).toString() + "3"] = { ...e, abilityEffectType: "TSUBAME", value1: 0, value2: 0, value3: 0 }; // This is just to trigger the active condition
            }
        })

        if (this.buffMult < 0) this.buffMult = 0;
        if (this.debuffMult < 0) this.debuffMult = 0;
        this.effects = Object.values(this.unscalableEffects).concat(Object.values(this.scalableEffects).map(e => {
            let v = e.value1;
            const abilityEffectType = e.abilityEffectType.replace("AIM_", "")
            if (abilityEffectType.startsWith("DWN_") || abilityEffectType.startsWith("DOWN_") || abilityEffectType.startsWith("UP_RCV_")) {
                v *= this.debuffMult;
            } else if (abilityEffectType.startsWith("UP_")) {
                v *= this.buffMult;
            }
            return { ...e, value1: v, turn: e.turn + this.debuffTurnBonus }
        }));
        this.effects.forEach(e => {
            const dotType = e.abilityEffectType.replace(/_(ATK|DEF|HP)$/, "");

            if (e.abilityEffectType === "ADDITIONAL_DAMAGE") {
                this.idealSupportPortrait = SupportIdealPortrait.ADD_DMG;
            } else if (dotType !== Ailment.WEAKNESS && Object.values(Ailment).includes(dotType as Ailment)) {
                this.idealSupportPortrait = SupportIdealPortrait.DOT_APPLIER;
            }
        });
    }

    // map is a pre-built index from (id*100+lvl) to matching effect rows (see passiveDetailsByMstId /
    // skillDetailsByMstId in utils/helpers.ts) — O(1) lookup instead of scanning the whole table.
    addEffect(map: Map<number, SkillDetail[]>, id: number, lvl: number, affectedByMult: boolean, retainDupes = false) {
        const obj = map.get(id * 100 + lvl) ?? [];
        const target = affectedByMult ? this.scalableEffects : this.unscalableEffects;
        for (const e of obj) {
            let key = skillDetailId(e).toString();
            if (retainDupes) {
                let idx = 1;
                while (key in target) {
                    key = `${skillDetailId(e)}${idx++}`;
                }
            }
            if (Object.keys(target).includes(key)) {
                console.warn(`Duplicate effect ID ${key} on ${this.name} for`, e)
            } else {
                target[key] = e;
            }
        }
    }
}
